async (page) => {
  // Get system memory information using Node.js
  const os = require('os');

  // Get total memory
  const totalMemory = os.totalmem();
  const freeMemory = os.freemem();
  const usedMemory = totalMemory - freeMemory;

  // Convert bytes to MB
  const totalMemoryMB = (totalMemory / (1024 * 1024)).toFixed(2);
  const freeMemoryMB = (freeMemory / (1024 * 1024)).toFixed(2);
  const usedMemoryMB = (usedMemory / (1024 * 1024)).toFixed(2);
  const usagePercent = ((usedMemory / totalMemory) * 100).toFixed(2);

  return {
    totalMemoryMB,
    freeMemoryMB,
    usedMemoryMB,
    usagePercent
  };
}

